package uz.mirix.tracelens.internal;
import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import uz.mirix.tracelens.*;import java.sql.*;import static org.assertj.core.api.Assertions.assertThat;
class JdbcProxyFactoryTest{@AfterEach void clear(){TraceContextHolder.clear();}@Test void recordsPreparedStatementWithoutParameterValues()throws Exception{JdbcDataSource ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:tracelens;DB_CLOSE_DELAY=-1");TraceLensProperties p=new TraceLensProperties();TraceContext c=new TraceContext("GET","/users",10);TraceContextHolder.bind(c);try(Connection raw=ds.getConnection();Connection connection=JdbcProxyFactory.wrapConnection(raw,p);PreparedStatement statement=connection.prepareStatement("select ? as secret")){statement.setString(1,"do-not-log-me");statement.executeQuery();}TraceReport report=c.finish("/users",200,null,System.nanoTime());assertThat(report.spans()).filteredOn(s->s.category()==TraceCategory.SQL).singleElement().satisfies(s->{assertThat(s.name()).contains("select ? as secret");assertThat(s.name()).doesNotContain("do-not-log-me");});}}
